// Approach: Skip leading spaces, read an optional sign, and recursively consume digits. Clamp as soon
//   as the signed value would exceed 32-bit range.
#include <string>
#include <climits>
#include <cctype>
using namespace std;
int parseDigits(const string& s, int i, long long value, int sign) {
    if (i == (int)s.size() || !isdigit((unsigned char)s[i]))
        return (int)(sign * value);
    int digit = s[i] - '0';
    long long limit = sign == 1 ? INT_MAX : -(long long)INT_MIN;
    if (value > (limit - digit) / 10)
        return sign == 1 ? INT_MAX : INT_MIN;
    return parseDigits(s, i + 1, value * 10 + digit, sign);
}
int myAtoi(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == ' ') ++i;
    int sign = 1;
    if (i < (int)s.size() && (s[i] == '+' || s[i] == '-'))
        sign = s[i++] == '-' ? -1 : 1;
    return parseDigits(s, i, 0, sign);
}

