// Approach: Exponentiation by squaring: compute the half-power once, square it, and multiply by x
//   only for an odd exponent. Use a wider exponent for INT_MIN.
double positivePower(double x, long long n) {
    if (n == 0) return 1.0;
    double half = positivePower(x, n / 2);
    double result = half * half;
    return n % 2 ? result * x : result;
}
double myPow(double x, int n) {
    long long exponent = n;
    if (exponent < 0) return 1.0 / positivePower(x, -exponent);
    return positivePower(x, exponent);
}

s7-count-good-numbers.code:
// Approach: Even-indexed positions have 5 even-digit choices (0, 2, 4, 6, 8); odd-indexed positions
//   have 4 prime-digit choices (2, 3, 5, 7). Multiply the counts using modular exponentiation.
static constexpr long long MOD = 1000000007;
long long modPow(long long base, long long exponent) {
    long long answer = 1;
    while (exponent > 0) {
        if (exponent & 1) answer = answer * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return answer;
}
int countGoodNumbers(long long n) {
    return (int)(modPow(5, (n + 1) / 2) * modPow(4, n / 2) % MOD);
}

s7-sort-a-stack-using-recursion.code:
// Approach: Remove the top, sort the rest recursively, then insert the removed value into its sorted
//   position. Largest ends on top.
#include <stack>
using namespace std;
void insertSorted(stack<int>& st, int value) {
    if (st.empty() || st.top() <= value) {
        st.push(value);
        return;
    }
    int top = st.top();
    st.pop();
    insertSorted(st, value);
    st.push(top);
}
void sortStack(stack<int>& st) {
    if (st.empty()) return;
    int top = st.top();
    st.pop();
    sortStack(st);
    insertSorted(st, top);
}

