// Approach: Remove the top, reverse the remaining stack, then place the removed value at the bottom.
#include <stack>
using namespace std;
void pushBottom(stack<int>& st, int value) {
    // Descend to the empty stack, then rebuild with value at the bottom.
    if (st.empty()) { st.push(value); return; }
    int top = st.top();
    st.pop();
    pushBottom(st, value);
    st.push(top);
}
void reverseStack(stack<int>& st) {
    if (st.empty()) return;
    int top = st.top();
    st.pop();
    reverseStack(st);
    pushBottom(st, top);
}

