// Approach: At each position choose 0 or 1; each root-to-leaf path is one length-n binary string.
#include <string>
#include <vector>
using namespace std;
void buildBinary(int n, string& current, vector<string>& answer) {
    // Reaching length n means one complete binary string is ready.
    if ((int)current.size() == n) {
        answer.push_back(current);
        return;
    }
    current.push_back('0');
    buildBinary(n, current, answer);
    current.back() = '1';
    buildBinary(n, current, answer);
    current.pop_back();
}
vector<string> binaryStrings(int n) {
    vector<string> answer;
    if (n < 0) return answer;
    string current;
    buildBinary(n, current, answer);
    return answer;
}

