// Approach: Add '(' while fewer than n opens have been used; add ')' only when it cannot make the
//   prefix invalid.
#include <string>
#include <vector>
using namespace std;
void buildParentheses(int n, int open, int close,
                      string& current, vector<string>& answer) {
    if (close == n) {
        answer.push_back(current);
        return;
    }
    if (open < n) {
        current.push_back('(');
        buildParentheses(n, open + 1, close, current, answer);
        current.pop_back();
    }
    if (close < open) {
        current.push_back(')');
        buildParentheses(n, open, close + 1, current, answer);
        current.pop_back();
    }
}
vector<string> generateParenthesis(int n) {
    vector<string> answer;
    if (n < 0) return answer;
    string current;
    buildParentheses(n, 0, 0, current, answer);
    return answer;
}

