s7-combination-sum.code:
// Approach: Sort distinct positive candidates. At each index either reuse the current value or move
//   to the next candidate; stop when the remaining target is too small.
#include <algorithm>
#include <vector>
using namespace std;
void combinationDfs(const vector<int>& a, int i, int left,
                    vector<int>& path, vector<vector<int>>& answer) {
    if (left == 0) { answer.push_back(path); return; }
    if (i == (int)a.size() || a[i] > left) return;
    path.push_back(a[i]);
    combinationDfs(a, i, left - a[i], path, answer); // reuse
    path.pop_back();
    combinationDfs(a, i + 1, left, path, answer);    // skip
}
vector<vector<int>> combinationSum(vector<int> a, int target) {
    vector<vector<int>> answer;
    if (target < 0) return answer;
    a.erase(remove_if(a.begin(), a.end(), [](int x){ return x <= 0; }), a.end());
    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());
    vector<int> path;
    combinationDfs(a, 0, target, path, answer);
    return answer;
}

