// Approach: Sort candidates and try each remaining element once. At a recursion depth, skip repeated
//   equal values to avoid duplicate combinations.
#include <algorithm>
#include <vector>
using namespace std;
void uniqueCombinationDfs(const vector<int>& a, int start, int left,
                          vector<int>& path, vector<vector<int>>& answer) {
    if (left == 0) { answer.push_back(path); return; }
    for (int i = start; i < (int)a.size(); ++i) {
        if (i > start && a[i] == a[i - 1]) continue;
        if (a[i] > left) break; // candidates are positive and sorted
        path.push_back(a[i]);
        uniqueCombinationDfs(a, i + 1, left - a[i], path, answer);
        path.pop_back();
    }
}
