// Approach: Choose increasing numbers from 1 through 9. Stop when k numbers are chosen or the
//   remaining target is impossible.
#include <vector>
using namespace std;
void chooseDigits(int next, int slots, int left,
                  vector<int>& path, vector<vector<int>>& answer) {
    if (slots == 0) {
        if (left == 0) answer.push_back(path);
        return;
    }
    for (int value = next; value <= 9; ++value) {
        if (value > left) break;
        path.push_back(value);
        chooseDigits(value + 1, slots - 1, left - value, path, answer);
        path.pop_back();
    }
}
