// Approach: Map each digit from 2 to 9 to its letters and recurse through one digit at a time,
//   appending each possible letter.
#include <string>
#include <vector>
using namespace std;
void phoneDfs(const string& digits, int i, string& path,
              vector<string>& answer) {
    static const string letters[10] =
        {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    if (i == (int)digits.size()) { answer.push_back(path); return; }
    for (char ch : letters[digits[i] - '0']) {
        path.push_back(ch);
        phoneDfs(digits, i + 1, path, answer);
        path.pop_back();
    }
}
