    if (digits.empty()) return {};
    for (char ch : digits) if (ch < '2' || ch > '9') return {};
    vector<string> answer;
    string path;
    phoneDfs(digits, 0, path, answer);
    return answer;
}

s7-palindrome-partitioning.code:
// Approach: Precompute which substrings are palindromes, then backtrack from each position using only
//   palindromic prefixes.
#include <string>
#include <vector>
using namespace std;
void partitionDfs(const string& s, int start,
                  const vector<vector<char>>& pal,
                  vector<string>& path, vector<vector<string>>& answer) {
    if (start == (int)s.size()) { answer.push_back(path); return; }
    for (int end = start; end < (int)s.size(); ++end) {
        if (!pal[start][end]) continue;
        path.push_back(s.substr(start, end - start + 1));
        partitionDfs(s, end + 1, pal, path, answer);
        path.pop_back();
    }
}
vector<vector<string>> partition(const string& s) {
    int n = (int)s.size();
    vector<vector<char>> pal(n, vector<char>(n, false));
    for (int start = n - 1; start >= 0; --start)
        for (int end = start; end < n; ++end)
            pal[start][end] = s[start] == s[end]
                && (end - start < 2 || pal[start + 1][end - 1]);
    vector<vector<string>> answer;
    vector<string> path;
    partitionDfs(s, 0, pal, path, answer);
    return answer;
}

