// Approach: Try every board cell as the first letter. DFS through four neighbors, temporarily marking
//   used cells so a path cannot reuse one cell.
#include <string>
#include <vector>
using namespace std;
bool searchFrom(vector<vector<char>>& board, const string& word,
                int r, int c, int i) {
    if (i == (int)word.size()) return true;
    if (r < 0 || c < 0 || r >= (int)board.size()
        || c >= (int)board[0].size() || board[r][c] != word[i])
        return false;
    char saved = board[r][c];
    board[r][c] = '#';
    bool found = searchFrom(board, word, r + 1, c, i + 1)
              || searchFrom(board, word, r - 1, c, i + 1)
              || searchFrom(board, word, r, c + 1, i + 1)
              || searchFrom(board, word, r, c - 1, i + 1);
    board[r][c] = saved;
    return found;
}
bool exist(vector<vector<char>>& board, const string& word) {
    if (word.empty()) return true;
    if (board.empty() || board[0].empty()) return false;
    for (int r = 0; r < (int)board.size(); ++r)
        for (int c = 0; c < (int)board[0].size(); ++c)
            if (searchFrom(board, word, r, c, 0)) return true;
    return false;
}

s7-n-queen.code:
// Approach: Place one queen per row while marking occupied columns and both diagonal directions.
//   Backtrack after each placement.
#include <string>
#include <vector>
using namespace std;
void queenDfs(int row, vector<string>& board,
              vector<char>& col, vector<char>& down, vector<char>& up,
              vector<vector<string>>& answer) {
    int n = (int)board.size();
    if (row == n) { answer.push_back(board); return; }
    for (int c = 0; c < n; ++c) {
        int d = row - c + n - 1, u = row + c;
        if (col[c] || down[d] || up[u]) continue;
        col[c] = down[d] = up[u] = 1;
        board[row][c] = 'Q';
        queenDfs(row + 1, board, col, down, up, answer);
        board[row][c] = '.';
        col[c] = down[d] = up[u] = 0;
    }
}
vector<vector<string>> solveNQueens(int n) {
    if (n < 0) return {};
    vector<string> board(n, string(n, '.'));
    vector<char> col(n), down(n ? 2 * n - 1 : 0), up(n ? 2 * n - 1 : 0);
    vector<vector<string>> answer;
    queenDfs(0, board, col, down, up, answer);
    return answer;
}

s7-rat-in-a-maze.code:
// Approach: DFS from the top-left to bottom-right, marking the current cell visited. Explore D, L, R,
//   U for lexicographically ordered paths.
#include <string>
#include <vector>
using namespace std;
void mazeDfs(const vector<vector<int>>& grid, int r, int c,
             vector<vector<char>>& used, string& path,
             vector<string>& answer) {
    int n = (int)grid.size();
    if (r == n - 1 && c == n - 1) {
        answer.push_back(path);
        return;
    }
    static const int dr[4] = {1, 0, 0, -1};
    static const int dc[4] = {0, -1, 1, 0};
    static const char step[4] = {'D', 'L', 'R', 'U'};
    used[r][c] = 1;
    for (int i = 0; i < 4; ++i) {
        int nr = r + dr[i], nc = c + dc[i];
        if (nr < 0 || nc < 0 || nr >= n || nc >= n
            || !grid[nr][nc] || used[nr][nc]) continue;
        path.push_back(step[i]);
        mazeDfs(grid, nr, nc, used, path, answer);
        path.pop_back();
    }
    used[r][c] = 0;
}
vector<string> findPaths(const vector<vector<int>>& grid) {
    int n = (int)grid.size();
    if (!n || !grid[0][0] || !grid[n - 1][n - 1]) return {};
    vector<vector<char>> used(n, vector<char>(n));
    vector<string> answer;
    string path;
    mazeDfs(grid, 0, 0, used, path, answer);
    return answer;
}

s7-m-coloring-problem.code:
// Approach: Assign colors vertex by vertex. Reject any color already used by a colored neighbor, and
//   backtrack if later vertices cannot be colored.
#include <vector>
using namespace std;
bool colorDfs(const vector<vector<int>>& graph, int v, int m,
              vector<int>& color) {
    if (v == (int)graph.size()) return true;
    for (int choice = 1; choice <= m; ++choice) {
        bool safe = true;
        for (int neighbor : graph[v])
            if (color[neighbor] == choice) { safe = false; break; }
        if (!safe) continue;
        color[v] = choice;
        if (colorDfs(graph, v + 1, m, color)) return true;
        color[v] = 0;
    }
    return false;
}
bool graphColoring(const vector<vector<int>>& graph, int m) {
    vector<int> color(graph.size(), 0);
    return colorDfs(graph, 0, m, color);
}

s7-sudoko-solver.code:
// Approach: Track used digits for rows, columns and 3×3 boxes with bitmasks. At each step choose the
//   empty cell with the fewest legal digits.
#include <vector>
using namespace std;
bool sudokuDfs(vector<vector<char>>& board, vector<pair<int,int>>& empty,
               int at, int row[9], int col[9], int box[9]) {
    if (at == (int)empty.size()) return true;
    int best = -1, fewest = 10;
    for (int i = at; i < (int)empty.size(); ++i) {
        int r = empty[i].first, c = empty[i].second;
        int choices = (~(row[r] | col[c] | box[(r / 3) * 3 + c / 3])) & 511;
        int count = __builtin_popcount((unsigned)choices);
        if (count < fewest) { fewest = count; best = i; }
    }
    if (fewest == 0) return false;
    swap(empty[at], empty[best]);
    int r = empty[at].first, c = empty[at].second;
    int b = (r / 3) * 3 + c / 3;
    int choices = (~(row[r] | col[c] | box[b])) & 511;
    for (int digit = 0; digit < 9; ++digit) {
        int bit = 1 << digit;
        if (!(choices & bit)) continue;
        board[r][c] = char('1' + digit);
        row[r] |= bit; col[c] |= bit; box[b] |= bit;
        if (sudokuDfs(board, empty, at + 1, row, col, box)) return true;
        row[r] ^= bit; col[c] ^= bit; box[b] ^= bit;
    }
    board[r][c] = '.';
    swap(empty[at], empty[best]);
    return false;
}
bool solveSudoku(vector<vector<char>>& board) {
    if (board.size() != 9) return false;
    int row[9] = {}, col[9] = {}, box[9] = {};
    vector<pair<int,int>> empty;
    for (int r = 0; r < 9; ++r) {
        if (board[r].size() != 9) return false;
        for (int c = 0; c < 9; ++c) {
            if (board[r][c] == '.') { empty.push_back({r, c}); continue; }
            int digit = board[r][c] - '1';
            if (digit < 0 || digit >= 9) return false;
            int bit = 1 << digit, b = (r / 3) * 3 + c / 3;
            if ((row[r] | col[c] | box[b]) & bit) return false;
            row[r] |= bit; col[c] |= bit; box[b] |= bit;
        }
    }
    return sudokuDfs(board, empty, 0, row, col, box);
}

s7-expression-add-operators.code:
// Approach: Try every next number without leading zeros. Track both the evaluated total and the last
//   signed term so multiplication can replace that term with term×value.
#include <string>
#include <vector>
using namespace std;
void expressionDfs(const string& digits, long long target, int pos,
                   long long total, long long last, string& expr,
                   vector<string>& answer) {
    if (pos == (int)digits.size()) {
        if (total == target) answer.push_back(expr);
        return;
    }
    long long value = 0;
    int oldSize = (int)expr.size();
    for (int end = pos; end < (int)digits.size(); ++end) {
        if (end > pos && digits[pos] == '0') break;
        value = value * 10 + digits[end] - '0';
        string part = digits.substr(pos, end - pos + 1);
        if (pos == 0) {
            expr += part;
            expressionDfs(digits, target, end + 1, value, value, expr, answer);
        } else {
            expr += "+" + part;
            expressionDfs(digits, target, end + 1, total + value, value, expr, answer);
            expr.resize(oldSize);
            expr += "-" + part;
            expressionDfs(digits, target, end + 1, total - value, -value, expr, answer);
            expr.resize(oldSize);
            expr += "*" + part;
            expressionDfs(digits, target, end + 1,
                          total - last + last * value, last * value, expr, answer);
        }
        expr.resize(oldSize);
    }
}
vector<string> addOperators(const string& digits, long long target) {
    vector<string> answer;
    if (digits.empty()) return answer;
    string expr;
    expressionDfs(digits, target, 0, 0, 0, expr, answer);
    return answer;
}

