// Approach: Let dp[i] mean the prefix ending before i can be segmented. Try only dictionary word
//   lengths from each reachable prefix.
#include <algorithm>
#include <string>
#include <unordered_set>
#include <vector>
using namespace std;
bool wordBreak(const string& s, const vector<string>& words) {
    unordered_set<string> dict(words.begin(), words.end());
    int longest = 0;
    for (const string& word : dict)
        longest = max(longest, (int)word.size());
    vector<char> dp(s.size() + 1, false);
    dp[0] = true;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (!dp[i]) continue;
        for (int length = 1; length <= longest && i + length <= (int)s.size(); ++length)
            if (dict.count(s.substr(i, length))) dp[i + length] = true;
    }
    return dp[s.size()];
}
